/*******************************************************************************
 * Code for BOARD_BootClockFRO10M configuration
 ******************************************************************************/
void BOARD_BootClockFRO10M_InitClockModule(clock_module_t module)
{
    switch(module) {
        case kClockModule_ROSC:
            /* Set the safe clock to AON_CPU to use FROdiv1. */
            CLOCK_AttachClk(kFROdiv1_to_AON_CPU);
            /* Set AON_CPU_CLK_DIV divider to value 1 and enable the clock gate. */
            CLOCK_SetClockDiv(kCLOCK_DIVAonCPU, 1U);
            /* Initialization of the ROSC only if it is not already running. */
            if (!CLOCK_IsRoscInitialized())
            {
                /* Configuration of the 32 kHz crystal oscillator */
                CLOCK_InitRosc(&roscConfig_BOARD_BootClockFRO10M);
            }
            /* Enable the 32 kHz crystal oscillator output to the AON and the Main domains. */
            AON__SYSCON_AON->XTAL_32K_CLKCTRL &= ~SYSCON_AON_XTAL_32K_CLKCTRL_XTAL_32K_CLK_CTRL_MASK;
            /* Enable the clock output of the XTAL32K from the AON_RTC. */
            AON__CGU->CLK_CONFIG |= CGU_CLK_CONFIG_XTAL32_OUT_EN_MASK;
            /* Enable the XTAL 32.768KHz towards the CGU. */
            AON__RTC_AON->CONFIG |= RTC_CONFIG_XTAL32_EN_MASK;
            break;
        case kClockModule_FRO:
            CLOCK_SetupFROAonClocking(10000000U);               /* Setup ROOT_CLK clock source */
            break;
        case kClockModule_FRO16K:
            PMU_EnableFRO16K(AON__PMU, true);                   /* Initialize the FRO16K clock source */
            PMU_UpdateFRO16KFreq(AON__PMU, kPMU_FRO16KOutput16KHz);/* Select the output frequency of the FRO16K */
            AON__PMU->PMU_DPD3_CTRL |= PMU_PMU_DPD3_CTRL_FRO16KHZ_ACT_MASK;/* Enable the FRO16K even during DPD3 and shutdown modes */
            break;
        case kClockModule_AON_CPU_ROOT_CLK:
            /* !< Switch AON_CPU to FROdiv1 */
            CLOCK_AttachClk(kFROdiv1_to_AON_CPU);
            /* !< Set AON_CPU_CLK_DIV divider to value 1 */
            CLOCK_SetClockDiv(kCLOCK_DIVAonCPU, 1U);
            break;
        case kClockModule_AON_COM_CLK:
            /* !< Switch AON_COM to FROdiv4 */
            CLOCK_AttachClk(kFROdiv4_to_AON_COM);
            /* !< Set COM_GRP_CLK_DIV divider to value 1 */
            CLOCK_SetClockDiv(kCLOCK_DIVAonCMP, 1U);
            break;
        case kClockModule_AON_TMR_GRP_CLK:
            /* !< Switch AON_TMR to FROdiv4 */
            CLOCK_AttachClk(kFROdiv4_to_AON_TMR);
            break;
        case kClockModule_AON_LPTMR_CLK:
            /* !< Switch AON_LPTMR to ON_TMR */
            CLOCK_AttachClk(AON_TMR_to_AON_LPTMR);
            break;
        case kClockModule_AON_KPP_CLK:
            /* !< Switch AON_KPP to FRO16K */
            CLOCK_AttachClk(kFRO16K_to_AON_KPP);
            break;
        case kClockModule_AON_LCD_CLK:
            /* !< Switch AON_LCD to FRO16K */
            CLOCK_AttachClk(kFRO16K_to_AON_LCD);
            break;
        case kClockModule_AON_LPADC_CLK:
            /* !< Switch AON_LPADC to FROdiv4 */
            CLOCK_AttachClk(kFROdiv4_to_AON_LPADC);
            break;
        case kClockModule_AON_ACMP0_CLK:
            /* !< Switch AON_CMP0 to FROdiv4 */
            CLOCK_AttachClk(kFROdiv4_to_AON_CMP0);
            /* !< Set AON_ACMP_CLK0_DIV divider to value 1 */
            CLOCK_SetClockDiv(kCLOCK_DIVAonACMP0CLK0, 1U);
            /* !< Set AON_ACMP_CLK1_DIV divider to value 1 */
            CLOCK_SetClockDiv(kCLOCK_DIVAonACMP0CLK1, 1U);
            break;
        default:
            assert(false);
            break;
    }
}

void BOARD_BootClockFRO10M(void)
{
    /* Enable APB clock gate for access to AON. */
    CLOCK_EnableClock(kCLOCK_GateAonAPB);
    BOARD_BootClockFRO10M_InitClockModule(kClockModule_FRO16K);
    BOARD_BootClockFRO10M_InitClockModule(kClockModule_ROSC);
    BOARD_BootClockFRO10M_InitClockModule(kClockModule_FRO);
    BOARD_BootClockFRO10M_InitClockModule(kClockModule_AON_CPU_ROOT_CLK);
    BOARD_BootClockFRO10M_InitClockModule(kClockModule_AON_COM_CLK);
    BOARD_BootClockFRO10M_InitClockModule(kClockModule_AON_TMR_GRP_CLK);
    BOARD_BootClockFRO10M_InitClockModule(kClockModule_AON_LPTMR_CLK);
    BOARD_BootClockFRO10M_InitClockModule(kClockModule_AON_KPP_CLK);
    BOARD_BootClockFRO10M_InitClockModule(kClockModule_AON_LCD_CLK);
    BOARD_BootClockFRO10M_InitClockModule(kClockModule_AON_LPADC_CLK);
    BOARD_BootClockFRO10M_InitClockModule(kClockModule_AON_ACMP0_CLK);

    /* Set SystemCoreClock variable */
    SystemCoreClock = BOARD_BOOTCLOCKFRO10M_AON_CPU_CLK;
}
